<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { NAlert, NButton, NCheckbox, NCollapse, NCollapseItem, NSelect, NTag } from 'naive-ui';
import type { BoardSnapshot } from '../types.ts';
import { fieldChanges, operationTitle } from '../lib/storyboard.ts';
import { formatDate } from '../lib/timeline.ts';
const props = defineProps<{ board: BoardSnapshot; disabled: boolean; editorDirty: boolean }>();
const emit = defineEmits<{ apply: [input: { id: string; acceptedOperationIds: string[] }]; renew: [id: string]; create: [] }>();
const selectedDraftId = ref<string | null>(null);
const accepted = ref<string[]>([]);
const drafts = computed(() => [...props.board.drafts].sort((a, b) => b.createdAt.localeCompare(a.createdAt)));
const selected = computed(() => drafts.value.find(draft => draft.id === selectedDraftId.value) || drafts.value.find(draft => draft.status === 'pending') || drafts.value[0]);
const stale = computed(() => selected.value?.baseRevision !== props.board.revision);
const options = computed(() => drafts.value.map(draft => ({ value: draft.id, label: `${draft.source === 'model' ? '推理草稿' : '手工草稿'} · ${formatDate(draft.createdAt)} · ${draft.status === 'applied' ? '已应用' : '待审阅'}` })));
watch(() => selected.value?.id, () => { accepted.value = []; });
function toggle(id: string, checked: boolean) { accepted.value = checked ? [...accepted.value.filter(value => value !== id), id] : accepted.value.filter(value => value !== id); }
</script>

<template>
  <section class="panel draft-review"><div class="panel-heading"><div class="heading-line"><h2>草稿审阅</h2><NTag size="small" :bordered="false">{{ drafts.filter(draft => draft.status === 'pending').length }} 份待审阅</NTag></div><NButton size="small" :disabled="disabled" @click="emit('create')">新建修改草稿</NButton></div><p v-if="!selected" class="draft-empty">推理建议和手工修改草稿会出现在这里。勾选希望接受的变化，再由你决定何时应用。</p><template v-else><NSelect v-model:value="selectedDraftId" :options="options" :placeholder="options.find(option => option.value === selected?.id)?.label" aria-label="选择草稿" /><div class="draft-meta"><span>基于分镜 r{{ selected.baseRevision }}</span><span>{{ selected.operations.length }} 项变更</span><span v-if="selected.status === 'applied'">已接受 {{ selected.acceptedOperationIds.length }} 项</span></div><NAlert v-if="selected.status === 'pending' && stale" type="warning" :show-icon="false" class="draft-alert">当前分镜已更新到 r{{ board.revision }}，这份草稿不能直接应用。可复制为基于最新分镜的新草稿，再逐项核对。<NButton text type="primary" :disabled="disabled" @click="emit('renew', selected.id)">以最新分镜重新审阅</NButton></NAlert><NAlert v-if="editorDirty && selected.status === 'pending'" type="info" :show-icon="false" class="draft-alert">镜头还有未保存内容，请先保存或放弃镜头修改，再应用草稿。</NAlert><div class="draft-operations"><article v-for="operation in selected.operations" :key="operation.id" class="draft-operation"><div class="draft-operation-title"><NCheckbox :checked="selected.status === 'applied' ? selected.acceptedOperationIds.includes(operation.id) : accepted.includes(operation.id)" :disabled="disabled || selected.status === 'applied' || stale || editorDirty" :aria-label="`接受${operationTitle(operation, board.shots)}`" @update:checked="toggle(operation.id, $event)" /><NTag size="small" :bordered="false" :type="operation.kind === 'delete' ? 'error' : operation.kind === 'add' ? 'success' : 'warning'">{{ operation.kind === 'add' ? '新增' : operation.kind === 'update' ? '修改' : '归档' }}</NTag><strong>{{ operationTitle(operation, board.shots) }}</strong></div><NCollapse><NCollapseItem :title="operation.kind === 'delete' ? '查看将归档的内容' : '查看字段变化'" :name="operation.id"><div class="field-differences"><div v-for="change in fieldChanges(operation, board.shots)" :key="change.key" class="field-difference"><span>{{ change.label }}</span><div v-if="operation.kind !== 'add'" class="diff-before"><small>当前</small><p>{{ change.before }}</p></div><div v-if="operation.kind !== 'delete'" class="diff-after"><small>草稿</small><p>{{ change.after }}</p></div></div></div></NCollapseItem></NCollapse></article></div><div v-if="selected.status === 'pending'" class="draft-footer"><span>{{ accepted.length }} / {{ selected.operations.length }} 项已勾选</span><NButton type="primary" :disabled="disabled || stale || editorDirty || !accepted.length" @click="emit('apply', { id: selected.id, acceptedOperationIds: accepted })">仅应用勾选项</NButton></div><p class="panel-footnote">应用后只保留已接受的变更，未勾选项不会自动写入分镜；原素材和历史候选保留。</p></template></section>
</template>
